#!/usr/bin/env python3
"""Generate/check neutral store drafts against the actual content catalogs."""
import argparse,json,re
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
LOCALES=('de','en','ru')
def counts(root=ROOT):
    tasks=json.loads((root/'games/quest/tasks.json').read_text())['tasks']
    subjects=Counter(t['subject'] for t in tasks)
    if len(set(subjects.values()))!=1:raise ValueError('Subject sizes differ; revise the listing instead of claiming an equal count')
    scene=re.search(r'const IDS := (\[[^\n]+\])',(root/'core/quest/scenery.gd').read_text())
    music=json.loads((root/'assets/music/manifest.json').read_text())
    languages=json.loads((root/'games/quest/languages.json').read_text())
    return dict(subjects=len(subjects),per_subject=next(iter(subjects.values())),base=len(tasks),bonus=sum(len(t.get('bonuses',[])) for t in tasks),scenes=len(json.loads(scene[1])),music=len(music['tracks']),languages=len(languages['locales']))
def documents(root=ROOT):
    c=counts(root)
    titles={'de':('Kinderwelt – Lernen entdecken','Rätsel, eigene Figuren und freiwillige Bonusaufgaben.'),'en':('Kinderwelt: Learn & Explore','Puzzles, your own character and optional bonus challenges.'),'ru':('Мир знаний — приключения','Загадки, свой персонаж и необязательные бонусные задания.')}
    descriptions={
      'de':f"Entdecke {c['subjects']} Fächer mit je {c['per_subject']} Stationen: Mathe, Deutsch, Logik, Physik, Biologie, Chemie, Mensch und Geografie. Zu den {c['base']} Grundaufgaben kommen {c['bonus']} freiwillige Boni. Bewege eine Fantasiefigur durch {c['scenes']} wählbare Kulissen und sammle dauerhaft auf dem Gerät gespeicherte Punkte. Erwachsene können lokal ein eigenes Figurenbild auswählen, zuschneiden und wieder löschen. Keine Fotos werden von der App übertragen. Mit {c['languages']} Sprachen und {c['music']} klassischen Klavierwiedergaben. Ohne Konten, Werbung, Käufe oder Zeitlimits. Die Sprachlernaufgaben passen zur gewählten Sprache. Für Klasse 1–2, mit anspruchsvolleren Aufgaben; Erwachsene können auf Wunsch begleiten.",
      'en':f"Explore {c['subjects']} subjects with {c['per_subject']} stations each: maths, English, logic, physics, biology, chemistry, the human body and geography. The {c['base']} main tasks include {c['bonus']} optional bonus challenges. Move a fictional character through {c['scenes']} selectable scenes and collect points saved on your device. Adults can choose, crop and remove a local character image. The app does not transmit photos. Includes {c['languages']} languages and {c['music']} classical piano renditions. No accounts, advertising, purchases or timers. Language-learning tasks match your chosen language. Designed for early primary school, with more challenging tasks and optional adult help.",
      'ru':f"Исследуй {c['subjects']} предметов, в каждом по {c['per_subject']} станций: математика, русский язык, логика, физика, биология, химия, человек и география. К {c['base']} основным заданиям добавлены {c['bonus']} необязательных бонусных заданий. Выбери сказочного персонажа и одну из {c['scenes']} декораций. Заработанные очки сохраняются на устройстве. Взрослый может выбрать своё изображение персонажа, обрезать и удалить его. Приложение не передаёт фотографии. Доступны {c['languages']} языка и {c['music']} фортепианных исполнений классической музыки. Без учётных записей, рекламы, покупок и таймера. Языковые задания соответствуют выбранному языку. Для первых классов, с более сложными заданиями и добровольной помощью взрослых."
    }
    result={}
    for locale in LOCALES:
        title,short=titles[locale]
        if len(title)>30 or len(short)>80:raise ValueError('Store title/short text exceeds the planned limit')
        result[f'listing.{locale}.md']=f'# Store listing — {locale} (operator-review draft)\n\nGenerated by `python3 scripts/store/listing.py --write`; do not edit counts by hand. No learning-effect or Play-approval claim.\n\n## Title\n\n{title}\n\n## Short description\n\n{short}\n\n## Full description\n\n{descriptions[locale]}\n\n## Operator fields\n\nPublisher: {{{{HERAUSGEBER}}}}. Support: {{{{SUPPORT_EMAIL}}}}. Privacy URL: {{{{DATENSCHUTZ_URL}}}}. Confirm category, child age groups, rights and final screenshots in Play Console. Neutral variant only.\n'
    return result
def check(root=ROOT):
    for name,expected in documents(root).items():
        if (root/'docs/play'/name).read_text()!=expected:raise ValueError('Stale listing: '+name+'; regenerate and review')
    return counts(root)
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);group=p.add_mutually_exclusive_group();group.add_argument('--write',action='store_true');group.add_argument('--check',action='store_true');a=p.parse_args()
    if a.write:
        for name,value in documents().items():(ROOT/'docs/play'/name).write_text(value)
    print('Store listing counts: PASS',check())
